CREATE TABLE `orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_type` enum('call','order') NOT NULL DEFAULT 'order',
  `customer_name` varchar(100) NOT NULL,
  `customer_phone` varchar(20) NOT NULL,
  `customer_email` varchar(100) DEFAULT NULL,
  `customer_address` varchar(255) DEFAULT NULL,
  `comment` text DEFAULT NULL,
  `attachment` varchar(255) DEFAULT NULL,
  `status` enum('new','in_progress','closed') DEFAULT 'new',
  `admin_comment` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `pages` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `slug` varchar(200) NOT NULL,
  `content` longtext DEFAULT NULL,
  `meta_title` varchar(200) DEFAULT NULL,
  `meta_description` varchar(300) DEFAULT NULL,
  `is_visible` tinyint(1) DEFAULT 1,
  `sort_order` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `is_visible`, `sort_order`) VALUES
(1, 'О пекарне', 'about', '<figure class=\"page-photo\">\r\n    <img src=\"uploads/products/o-pekarne.jpg\" alt=\"Витрина пекарни «Домашний хлеб»\">\r\n    <figcaption>Утренняя выкладка на Хлебной, 15: хлеб, багеты и печенье под колпаками</figcaption>\r\n</figure>\r\n\r\n<p class=\"page-lead\">«Домашний хлеб» — семейная пекарня в центре Москвы. Мы печём с 2014 года: без заморозки, без конвейера и без «улучшителей». Каждую буханку формуют руками, а тесто живёт своей жизнью — иногда дольше, чем рабочий день пекаря.</p>\r\n\r\n<p>История началась на маленькой кухне у Анны и Павла Ковалёвых. Первую закваску Анна привезла из поездки к бабушке в Коломну, первую партию хлеба продали соседям в тот же вечер. Через год появилась витрина на Хлебной, 15, ещё через три — своя подовая печь и команда из восьми человек. Адрес с тех пор не менялся: мы сознательно остаёмся одной пекарней, а не сетью.</p>\r\n\r\n<h2>Как проходит наш день</h2>\r\n<p>Ночная смена выходит к 23:00. Михаил ставит опару, кормит закваску и убирает тесто в холод. К шести утра первая закладка уже на поду: пшеничный, бородинский, багеты. К девяти выходят булочки и круассаны, к часу дня — пирожки, к пяти — вечерняя партия и печенье. Если изделие закончилось на витрине, мы не «достаём из морозилки» — пишем в блокнот и печём в ближайшую закладку.</p>\r\n<p>Гостям можно зайти просто посмотреть и понюхать. Мы не гоним с порога, даём отломить корочку и рассказываем состав. Вчерашнюю выпечку не выбрасываем: её можно забрать со скидкой 30% или мы отдаём её в фонд помощи «Тёплый ломтик».</p>\r\n\r\n<h2>Кто стоит у печи</h2>\r\n<div class=\"page-cards\">\r\n    <div class=\"page-card\">\r\n        <h3>Анна Ковалёва</h3>\r\n        <p>Шеф-пекарь и соосновательница. Отвечает за закваску, дегустацию новых рецептов и работу с фермерами. Говорит, что хлеб «не любит спешки и громкой музыки».</p>\r\n    </div>\r\n    <div class=\"page-card\">\r\n        <h3>Павел Ковалёв</h3>\r\n        <p>Управляет залом, доставкой и поставками. Когда-то возил хлеб на своей «Газели», теперь собирает маршруты курьеров так, чтобы багет не успел остыть.</p>\r\n    </div>\r\n    <div class=\"page-card\">\r\n        <h3>Михаил Орлов</h3>\r\n        <p>Ночной пекарь. Знает печь по звуку дверцы. Именно он ставит опару и делает надрез «ушком» на пшеничных буханках.</p>\r\n    </div>\r\n    <div class=\"page-card\">\r\n        <h3>Елена Савельева</h3>\r\n        <p>Кондитер сдобного цеха: булочки с маком и корицей, круассаны, печенье. Считает, что глазурь должна быть тонкой — «чтобы не спрятать корицу».</p>\r\n    </div>\r\n</div>\r\n\r\n<blockquote class=\"page-quote\">\r\n    Хлеб не терпит спешки. Ему нужно время, тепло рук и немного тишины — всё остальное сделает закваска.\r\n    <cite>Анна Ковалёва, шеф-пекарь</cite>\r\n</blockquote>\r\n\r\n<h2>Что для нас важно</h2>\r\n<ul>\r\n    <li>Только свежая выпечка дня — без заморозки полуфабрикатов.</li>\r\n    <li>Понятный состав: его можно спросить у любого пекаря за прилавком.</li>\r\n    <li>Небольшая суточная загрузка печи. Лучше закончить партию, чем гнать объём.</li>\r\n    <li>Соседи и постоянные гости: многих мы знаем по имени и помним, какой хлеб они берут по пятницам.</li>\r\n</ul>\r\n\r\n<div class=\"page-note\">\r\n    <h3>Приходите в гости</h3>\r\n    <p>Пекарня на ул. Хлебной, 15 работает ежедневно с 6:00 до 22:00. Можно взять кофе с собой, попробовать хлеб перед покупкой и оформить предзаказ к празднику. Если не получается заехать — оставьте заявку на сайте, привезём тёплым.</p>\r\n</div>', 1, 0),
(2, 'Состав и качество', 'quality', '<p class=\"page-lead\">Мы отвечаем за каждый грамм в тесте. Ниже — не рекламный список, а то, из чего на самом деле печётся «Домашний хлеб»: кто поставляет муку, масло и яйца, чего нет в составе и как мы проверяем свежесть.</p>\r\n\r\n<h2>Почему состав такой короткий</h2>\r\n<p>Базовый пшеничный хлеб у нас состоит из четырёх вещей: мука, вода, соль и закваска. В бородинском добавляются ржаная мука, солод и кориандр. В сдобе — сливочное масло и яйца. Никаких Е-шек «для пышности», пальмового жира, сухого молока «для цвета» и консервантов «чтобы доехало до Владивостока». Нам не нужно, чтобы батон лежал две недели: он должен быть съеден за два дня.</p>\r\n<p>Если гость спрашивает про аллергены, мы не отправляем его читать мелкий шрифт на этикетке. Состав каждого изделия висит на карточках у витрины, а полный список можно получить у смены или в WhatsApp.</p>\r\n\r\n<h2>Кто нас кормит зерном</h2>\r\n<p>Поставщиков мы выбирали несколько лет и не меняем их ради скидки в два рубля. С каждым хозяйством у нас прямой договор: приезжаем на мельницу и на ферму хотя бы раз в сезон.</p>\r\n<div class=\"page-cards\">\r\n    <div class=\"page-card\">\r\n        <h3>Мельница «Коломенский помол»</h3>\r\n        <p><strong>Мука пшеничная высшего сорта</strong> из зерна «Московская 39». Тонкий помол, стабильная клейковина. Именно на ней стоит наш белый хлеб и багеты. Мельница в Ступинском районе, до пекарни — одна ночная поставка в неделю.</p>\r\n    </div>\r\n    <div class=\"page-card\">\r\n        <h3>«Старорусский жернов»</h3>\r\n        <p><strong>Ржаная обдирная и цельнозерновая мука</strong> с каменных жерновов. Новгородская область. Из неё получается бородинский с влажным мякишем и хлеб на закваске, который живёт до пяти дней.</p>\r\n    </div>\r\n    <div class=\"page-card\">\r\n        <h3>Фермы «Рогачёво»</h3>\r\n        <p><strong>Сливочное масло 82,5%</strong> и фермерская сметана. Вологодская область. Масло идёт в круассаны, булочки с корицей и печенье. Растительных заменителей в сдобе нет.</p>\r\n    </div>\r\n    <div class=\"page-card\">\r\n        <h3>Птичник «Летово»</h3>\r\n        <p><strong>Отборные яйца С0</strong> с Калужской области. Для сдобы, пирожков и глазури. Если партия не проходит наш входной контроль по запаху и цветку желтка — возвращаем целиком.</p>\r\n    </div>\r\n    <div class=\"page-card\">\r\n        <h3>«Восточный двор»</h3>\r\n        <p><strong>Мак, корица, какао, ваниль</strong>. Пряности фасуют под нас небольшими мешками, чтобы не выдыхались на складе. Корицу берём цейлонскую, не кассию «для запаха».</p>\r\n    </div>\r\n    <div class=\"page-card\">\r\n        <h3>Наша закваска «Хлебная»</h3>\r\n        <p>Живёт с первого дня пекарни, с 2014 года. Кормим дважды в сутки мукой «Коломенского помола» и фильтрованной водой. Никаких сухих заквасок из пакетика.</p>\r\n    </div>\r\n</div>\r\n\r\n<h2>Что внутри популярных изделий</h2>\r\n<div class=\"page-table-wrap\">\r\n<table class=\"page-table\">\r\n    <thead>\r\n        <tr>\r\n            <th>Изделие</th>\r\n            <th>Основа</th>\r\n            <th>Чего нет</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td>Белый хлеб, багет</td>\r\n            <td>Пшеничная мука, вода, соль, закваска</td>\r\n            <td>Дрожжи быстрого действия, сахар, масло</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Бородинский, чёрный хлеб</td>\r\n            <td>Рожь, солод, кориандр, закваска</td>\r\n            <td>Краситель, патока «для цвета»</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Булочки с маком и корицей</td>\r\n            <td>Сдоба на масле 82,5%, яйца, мак / корица</td>\r\n            <td>Маргарин, сухой крем</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Круассан</td>\r\n            <td>Слоение на сливочном масле, мука «Коломенская»</td>\r\n            <td>Спред, заморозка заготовки</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Пирожки</td>\r\n            <td>Дрожжевое тесто, начинка дня: капуста, мясо, яблоко, вишня</td>\r\n            <td>Соевый фарш, начинка из консервов</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Печенье</td>\r\n            <td>Мука, масло, яйца, какао или мята</td>\r\n            <td>Гидрогенизированные жиры</td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n</div>\r\n\r\n<h2>Как мы проверяем качество</h2>\r\n<p>Каждая поставка муки проходит пробный замес: смотрим водопоглощение и как тесто ведёт себя через 16 часов холода. Яйца и масло принимают по накладной и по запаху — формальности мало. Готовую партию пекарь пробует сам: если корочка «резиновая» или мякиш сырой, закладка не уходит на витрину.</p>\r\n<p>Раз в месяц независимая лаборатория «Зерно-тест» на Красной Пресне делает смывы с оборудования и проверяет хлеб на дрожжи, плесень и остатки моющих средств. Протоколы лежат в папке у смены, их можно посмотреть.</p>\r\n\r\n<div class=\"page-note\">\r\n    <h3>Аллергены и особые просьбы</h3>\r\n    <p>В пекарне работают пшеница, рожь, молоко, яйца, мак и орехи (в части печенья). Полностью «безглютенового» цеха у нас нет, и мы об этом честно говорим. Зато есть хлеб на закваске без прессованных дрожжей, постные пирожки без молока и несладкие багеты. Напишите заранее — подскажем, что можно взять, и придержим партию.</p>\r\n</div>\r\n\r\n<h2>Как хранить</h2>\r\n<ul>\r\n    <li>Пшеничный хлеб и багет — в бумаге или льняном мешке, до двух суток при комнатной температуре.</li>\r\n    <li>Ржаной на закваске — до пяти дней, с каждым днём он становится ароматнее.</li>\r\n    <li>Сдобу и пирожки лучше съесть в день покупки, максимум на следующее утро.</li>\r\n    <li>Подсохший ломоть: сбрызнуть водой и 5 минут в духовке при 180 °C.</li>\r\n    <li>В полиэтилене хлеб «задыхается» — мы в него не упаковываем.</li>\r\n</ul>', 1, 0),
(3, 'Доставка', 'delivery', '<p class=\"page-lead\">Доставляем выпечку по Москве и ближайшему Подмосковью так, чтобы она приехала ещё тёплой. Курьер забирает заказ после выпечки, а не со склада вчерашнего дня. Ниже — зоны, сроки, цены и то, как оформить доставку или самовывоз.</p>\r\n\r\n<h2>Как это работает</h2>\r\n<p>Вы собираете корзину на сайте или звоните с 6:00 до 22:00. Менеджер перезванивает, подтверждает состав, адрес и слот. Заказы, оформленные до 11:00, везём в тот же день. После 11:00 — либо вечерний слот, либо утро следующего дня, как удобнее.</p>\r\n<p>Курьеры едут на автомобилях с термокоробками. Хлеб перед упаковкой остывает на решётке около 40 минут: если убрать его горячим, он отсыреет в пакете. Поэтому «за 15 минут из печи до двери» мы не обещаем — обещаем, что корочка останется хрустящей.</p>\r\n\r\n<h2>Зоны и время в пути</h2>\r\n<div class=\"page-table-wrap\">\r\n<table class=\"page-table\">\r\n    <thead>\r\n        <tr>\r\n            <th>Зона</th>\r\n            <th>Ориентир</th>\r\n            <th>Доставка</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td>Центр и Садовое кольцо</td>\r\n            <td>Арбат, Замоскворечье, Хлебная, 15</td>\r\n            <td>от 30 минут, 250 ₽</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Внутри ТТК</td>\r\n            <td>Хамовники, Таганка, Мещанский</td>\r\n            <td>40–70 минут, 250 ₽</td>\r\n        </tr>\r\n        <tr>\r\n            <td>В пределах МКАД</td>\r\n            <td>Большая часть районов Москвы</td>\r\n            <td>обычно до 90 минут, 350 ₽</td>\r\n        </tr>\r\n        <tr>\r\n            <td>За МКАД, до 15 км</td>\r\n            <td>Мытищи, Химки, Одинцово, Реутов</td>\r\n            <td>по слоту, 500 ₽</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Дальше 15 км</td>\r\n            <td>По договорённости</td>\r\n            <td>считаем отдельно, фиксируем время</td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n</div>\r\n\r\n<div class=\"page-cards\">\r\n    <div class=\"page-card\">\r\n        <h3>Минимальный заказ</h3>\r\n        <p><strong>500 ₽</strong> на доставку. При заказе от <strong>1000 ₽</strong> кладём домашнее печенье в подарок. От <strong>2500 ₽</strong> доставка по Москве внутри МКАД — бесплатно.</p>\r\n    </div>\r\n    <div class=\"page-card\">\r\n        <h3>Оплата</h3>\r\n        <p>Картой курьеру, переводом или наличными. Для офисов — счёт и закрывающие документы на ООО «Домашний хлеб».</p>\r\n    </div>\r\n    <div class=\"page-card\">\r\n        <h3>Самовывоз</h3>\r\n        <p>Хлебная, 15. Собираем заказ к указанному времени и держим его тёплым. Очереди в утренний час пик обычно нет: предзаказ забирают без ожидания у кассы.</p>\r\n    </div>\r\n    <div class=\"page-card\">\r\n        <h3>Предзаказ к событию</h3>\r\n        <p>Торты, пироги и коробочные наборы — за 24–48 часов. На свадьбу и корпоратив считаем смету и можем приехать с дегустацией.</p>\r\n    </div>\r\n</div>\r\n\r\n<h2>Офисы, завтраки и мероприятия</h2>\r\n<p>Раз в неделю возим хлеб в несколько редакций и небольших офисов на Патриарших и в Замоскворечье. Можно договориться о графике: например, каждый вторник и пятницу к 8:30 — корзина с багетами, круассанами и пирожками. Нарезаем, раскладываем по коробкам, оставляем счёт.</p>\r\n<p>Для дегустаций на 10–30 человек собираем «хлебный сет»: 4–5 видов, масло, варенье с фермы «Рогачёво» и карточки с составом. Пишите на info@bakery.ru — пришлём актуальный прайс.</p>\r\n\r\n<h2>Как упаковываем</h2>\r\n<ul>\r\n    <li>Хлеб и багеты — в крафт, чтобы корочка дышала.</li>\r\n    <li>Сдоба и пирожки — в коробку с пергаментом, отдельно от хлеба, чтобы не отсырели.</li>\r\n    <li>Печенье — в бумажный пакет или жестяную банку, если это подарок.</li>\r\n    <li>На длинные маршруты за МКАД ставим термочехол. Полиэтилен не используем.</li>\r\n</ul>\r\n\r\n<div class=\"page-note\">\r\n    <h3>Если что-то пошло не так</h3>\r\n    <p>Опоздали больше чем на 30 минут от слота — доставка за наш счёт. Приехало не то или выпечка помялась — меняем или возвращаем деньги, без спора. Напишите в WhatsApp или на info@bakery.ru, приложите фото. Нам важнее, чтобы вы заказали ещё раз, чем выиграть один чек.</p>\r\n</div>\r\n\r\n<p>Оформить доставку можно в <a href=\"index.php#order\">форме на главной</a> или по телефону +7 (499) 123-45-67. Самовывоз — ул. Хлебная, 15, ежедневно с 6:00 до 22:00.</p>', 1, 0),
(4, 'Политика конфиденциальности', 'privacy', '<p class=\"page-lead\">Политика в отношении обработки персональных данных составлена в соответствии с требованиями Федерального закона от 27.07.2006 №&nbsp;152-ФЗ «О персональных данных» и определяет порядок обработки персональных данных, а также меры по их защите.</p>\r\n\r\n<div class=\"page-doc-meta\">\r\n    <div>\r\n        <span>Оператор</span>\r\n        <strong>Ковалёва Анна Георгиевна</strong>\r\n    </div>\r\n    <div>\r\n        <span>Сайт</span>\r\n        <a href=\"https://homemadebread.ru\">https://homemadebread.ru</a>\r\n    </div>\r\n    <div>\r\n        <span>Контакт</span>\r\n        <a href=\"mailto:info@homebread.ru\">info@homebread.ru</a>\r\n    </div>\r\n</div>\r\n\r\n<nav class=\"page-toc\" aria-label=\"Разделы политики\">\r\n    <a href=\"#p1\">1. Общие положения</a>\r\n    <a href=\"#p2\">2. Понятия</a>\r\n    <a href=\"#p3\">3. Права оператора</a>\r\n    <a href=\"#p4\">4. Права субъектов</a>\r\n    <a href=\"#p5\">5. Принципы</a>\r\n    <a href=\"#p6\">6. Цели</a>\r\n    <a href=\"#p7\">7. Условия</a>\r\n    <a href=\"#p8\">8. Порядок обработки</a>\r\n    <a href=\"#p9\">9. Действия</a>\r\n    <a href=\"#p10\">10. Трансграничная передача</a>\r\n    <a href=\"#p11\">11. Конфиденциальность</a>\r\n    <a href=\"#p12\">12. Заключение</a>\r\n</nav>\r\n\r\n<h2 id=\"p1\">1. Общие положения</h2>\r\n<p>Настоящая политика обработки персональных данных составлена в соответствии с требованиями Федерального закона от 27.07.2006. №&nbsp;152-ФЗ «О персональных данных» (далее — Закон о персональных данных) и определяет порядок обработки персональных данных и меры по обеспечению безопасности персональных данных, предпринимаемые Ковалёвой Анной Георгиевной (далее — Оператор).</p>\r\n<p class=\"page-clause\"><span class=\"page-num\">1.1.</span><span>Оператор ставит своей важнейшей целью и условием осуществления своей деятельности соблюдение прав и свобод человека и гражданина при обработке его персональных данных, в том числе защиты прав на неприкосновенность частной жизни, личную и семейную тайну.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">1.2.</span><span>Настоящая политика Оператора в отношении обработки персональных данных (далее — Политика) применяется ко всей информации, которую Оператор может получить о посетителях веб-сайта <a href=\"https://homemadebread.ru\">https://homemadebread.ru</a>.</span></p>\r\n\r\n<h2 id=\"p2\">2. Основные понятия, используемые в Политике</h2>\r\n<dl class=\"page-terms\">\r\n    <div class=\"page-term\">\r\n        <dt>2.1. Автоматизированная обработка персональных данных</dt>\r\n        <dd>Обработка персональных данных с помощью средств вычислительной техники.</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.2. Блокирование персональных данных</dt>\r\n        <dd>Временное прекращение обработки персональных данных (за исключением случаев, если обработка необходима для уточнения персональных данных).</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.3. Веб-сайт</dt>\r\n        <dd>Совокупность графических и информационных материалов, а также программ для ЭВМ и баз данных, обеспечивающих их доступность в сети интернет по сетевому адресу <a href=\"https://homemadebread.ru\">https://homemadebread.ru</a>.</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.4. Информационная система персональных данных</dt>\r\n        <dd>Совокупность содержащихся в базах данных персональных данных и обеспечивающих их обработку информационных технологий и технических средств.</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.5. Обезличивание персональных данных</dt>\r\n        <dd>Действия, в результате которых невозможно определить без использования дополнительной информации принадлежность персональных данных конкретному Пользователю или иному субъекту персональных данных.</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.6. Обработка персональных данных</dt>\r\n        <dd>Любое действие (операция) или совокупность действий (операций), совершаемых с использованием средств автоматизации или без использования таких средств с персональными данными, включая сбор, запись, систематизацию, накопление, хранение, уточнение (обновление, изменение), извлечение, использование, передачу (распространение, предоставление, доступ), обезличивание, блокирование, удаление, уничтожение персональных данных.</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.7. Оператор</dt>\r\n        <dd>Государственный орган, муниципальный орган, юридическое или физическое лицо, самостоятельно или совместно с другими лицами организующие и/или осуществляющие обработку персональных данных, а также определяющие цели обработки персональных данных, состав персональных данных, подлежащих обработке, действия (операции), совершаемые с персональными данными.</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.8. Персональные данные</dt>\r\n        <dd>Любая информация, относящаяся прямо или косвенно к определенному или определяемому Пользователю веб-сайта <a href=\"https://homemadebread.ru\">https://homemadebread.ru</a>.</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.9. Персональные данные, разрешенные субъектом персональных данных для распространения</dt>\r\n        <dd>Персональные данные, доступ неограниченного круга лиц к которым предоставлен субъектом персональных данных путем дачи согласия на обработку персональных данных, разрешенных субъектом персональных данных для распространения в порядке, предусмотренном Законом о персональных данных (далее — персональные данные, разрешенные для распространения).</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.10. Пользователь</dt>\r\n        <dd>Любой посетитель веб-сайта <a href=\"https://homemadebread.ru\">https://homemadebread.ru</a>.</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.11. Предоставление персональных данных</dt>\r\n        <dd>Действия, направленные на раскрытие персональных данных определенному лицу или определенному кругу лиц.</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.12. Распространение персональных данных</dt>\r\n        <dd>Любые действия, направленные на раскрытие персональных данных неопределенному кругу лиц (передача персональных данных) или на ознакомление с персональными данными неограниченного круга лиц, в том числе обнародование персональных данных в средствах массовой информации, размещение в информационно-телекоммуникационных сетях или предоставление доступа к персональным данным каким-либо иным способом.</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.13. Трансграничная передача персональных данных</dt>\r\n        <dd>Передача персональных данных на территорию иностранного государства органу власти иностранного государства, иностранному физическому или иностранному юридическому лицу.</dd>\r\n    </div>\r\n    <div class=\"page-term\">\r\n        <dt>2.14. Уничтожение персональных данных</dt>\r\n        <dd>Любые действия, в результате которых персональные данные уничтожаются безвозвратно с невозможностью дальнейшего восстановления содержания персональных данных в информационной системе персональных данных и/или уничтожаются материальные носители персональных данных.</dd>\r\n    </div>\r\n</dl>\r\n\r\n<h2 id=\"p3\">3. Основные права и обязанности Оператора</h2>\r\n<h3>3.1. Оператор имеет право</h3>\r\n<ul>\r\n    <li>получать от субъекта персональных данных достоверные информацию и/или документы, содержащие персональные данные;</li>\r\n    <li>в случае отзыва субъектом персональных данных согласия на обработку персональных данных, а также направления обращения с требованием о прекращении обработки персональных данных, Оператор вправе продолжить обработку персональных данных без согласия субъекта персональных данных при наличии оснований, указанных в Законе о персональных данных;</li>\r\n    <li>самостоятельно определять состав и перечень мер, необходимых и достаточных для обеспечения выполнения обязанностей, предусмотренных Законом о персональных данных и принятыми в соответствии с ним нормативными правовыми актами, если иное не предусмотрено Законом о персональных данных или другими федеральными законами.</li>\r\n</ul>\r\n<h3>3.2. Оператор обязан</h3>\r\n<ul>\r\n    <li>предоставлять субъекту персональных данных по его просьбе информацию, касающуюся обработки его персональных данных;</li>\r\n    <li>организовывать обработку персональных данных в порядке, установленном действующим законодательством РФ;</li>\r\n    <li>отвечать на обращения и запросы субъектов персональных данных и их законных представителей в соответствии с требованиями Закона о персональных данных;</li>\r\n    <li>сообщать в уполномоченный орган по защите прав субъектов персональных данных по запросу этого органа необходимую информацию в течение 10 дней с даты получения такого запроса;</li>\r\n    <li>публиковать или иным образом обеспечивать неограниченный доступ к настоящей Политике в отношении обработки персональных данных;</li>\r\n    <li>принимать правовые, организационные и технические меры для защиты персональных данных от неправомерного или случайного доступа к ним, уничтожения, изменения, блокирования, копирования, предоставления, распространения персональных данных, а также от иных неправомерных действий в отношении персональных данных;</li>\r\n    <li>прекратить передачу (распространение, предоставление, доступ) персональных данных, прекратить обработку и уничтожить персональные данные в порядке и случаях, предусмотренных Законом о персональных данных;</li>\r\n    <li>исполнять иные обязанности, предусмотренные Законом о персональных данных.</li>\r\n</ul>\r\n\r\n<h2 id=\"p4\">4. Основные права и обязанности субъектов персональных данных</h2>\r\n<h3>4.1. Субъекты персональных данных имеют право</h3>\r\n<ul>\r\n    <li>получать информацию, касающуюся обработки его персональных данных, за исключением случаев, предусмотренных федеральными законами. Сведения предоставляются субъекту персональных данных Оператором в доступной форме, и в них не должны содержаться персональные данные, относящиеся к другим субъектам персональных данных, за исключением случаев, когда имеются законные основания для раскрытия таких персональных данных. Перечень информации и порядок ее получения установлен Законом о персональных данных;</li>\r\n    <li>требовать от оператора уточнения его персональных данных, их блокирования или уничтожения в случае, если персональные данные являются неполными, устаревшими, неточными, незаконно полученными или не являются необходимыми для заявленной цели обработки, а также принимать предусмотренные законом меры по защите своих прав;</li>\r\n    <li>выдвигать условие предварительного согласия при обработке персональных данных в целях продвижения на рынке товаров, работ и услуг;</li>\r\n    <li>на отзыв согласия на обработку персональных данных, а также на направление требования о прекращении обработки персональных данных;</li>\r\n    <li>обжаловать в уполномоченный орган по защите прав субъектов персональных данных или в судебном порядке неправомерные действия или бездействие Оператора при обработке его персональных данных;</li>\r\n    <li>на осуществление иных прав, предусмотренных законодательством РФ.</li>\r\n</ul>\r\n<h3>4.2. Субъекты персональных данных обязаны</h3>\r\n<ul>\r\n    <li>предоставлять Оператору достоверные данные о себе;</li>\r\n    <li>сообщать Оператору об уточнении (обновлении, изменении) своих персональных данных.</li>\r\n</ul>\r\n<p class=\"page-clause\"><span class=\"page-num\">4.3.</span><span>Лица, передавшие Оператору недостоверные сведения о себе, либо сведения о другом субъекте персональных данных без согласия последнего, несут ответственность в соответствии с законодательством РФ.</span></p>\r\n\r\n<h2 id=\"p5\">5. Принципы обработки персональных данных</h2>\r\n<p class=\"page-clause\"><span class=\"page-num\">5.1.</span><span>Обработка персональных данных осуществляется на законной и справедливой основе.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">5.2.</span><span>Обработка персональных данных ограничивается достижением конкретных, заранее определенных и законных целей. Не допускается обработка персональных данных, несовместимая с целями сбора персональных данных.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">5.3.</span><span>Не допускается объединение баз данных, содержащих персональные данные, обработка которых осуществляется в целях, несовместимых между собой.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">5.4.</span><span>Обработке подлежат только персональные данные, которые отвечают целям их обработки.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">5.5.</span><span>Содержание и объем обрабатываемых персональных данных соответствуют заявленным целям обработки. Не допускается избыточность обрабатываемых персональных данных по отношению к заявленным целям их обработки.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">5.6.</span><span>При обработке персональных данных обеспечивается точность персональных данных, их достаточность, а в необходимых случаях и актуальность по отношению к целям обработки персональных данных. Оператор принимает необходимые меры и/или обеспечивает их принятие по удалению или уточнению неполных или неточных данных.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">5.7.</span><span>Хранение персональных данных осуществляется в форме, позволяющей определить субъекта персональных данных, не дольше, чем этого требуют цели обработки персональных данных, если срок хранения персональных данных не установлен федеральным законом, договором, стороной которого, выгодоприобретателем или поручителем по которому является субъект персональных данных. Обрабатываемые персональные данные уничтожаются либо обезличиваются по достижении целей обработки или в случае утраты необходимости в достижении этих целей, если иное не предусмотрено федеральным законом.</span></p>\r\n\r\n<h2 id=\"p6\">6. Цели обработки персональных данных</h2>\r\n<div class=\"page-table-wrap\">\r\n<table class=\"page-table\">\r\n    <tbody>\r\n        <tr>\r\n            <th>Цель обработки</th>\r\n            <td>информирование Пользователя посредством отправки электронных писем</td>\r\n        </tr>\r\n        <tr>\r\n            <th>Персональные данные</th>\r\n            <td>электронный адрес; номера телефонов; имя; адрес</td>\r\n        </tr>\r\n        <tr>\r\n            <th>Правовые основания</th>\r\n            <td>уставные (учредительные) документы Оператора</td>\r\n        </tr>\r\n        <tr>\r\n            <th>Виды обработки персональных данных</th>\r\n            <td>сбор, запись, систематизация, накопление, хранение, уничтожение и обезличивание персональных данных; отправка информационных писем на адрес электронной почты; передача персональных данных</td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n</div>\r\n\r\n<h2 id=\"p7\">7. Условия обработки персональных данных</h2>\r\n<p class=\"page-clause\"><span class=\"page-num\">7.1.</span><span>Обработка персональных данных осуществляется с согласия субъекта персональных данных на обработку его персональных данных.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">7.2.</span><span>Обработка персональных данных необходима для достижения целей, предусмотренных международным договором Российской Федерации или законом, для осуществления возложенных законодательством Российской Федерации на оператора функций, полномочий и обязанностей.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">7.3.</span><span>Обработка персональных данных необходима для осуществления правосудия, исполнения судебного акта, акта другого органа или должностного лица, подлежащих исполнению в соответствии с законодательством Российской Федерации об исполнительном производстве.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">7.4.</span><span>Обработка персональных данных необходима для исполнения договора, стороной которого либо выгодоприобретателем или поручителем по которому является субъект персональных данных, а также для заключения договора по инициативе субъекта персональных данных или договора, по которому субъект персональных данных будет являться выгодоприобретателем или поручителем.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">7.5.</span><span>Обработка персональных данных необходима для осуществления прав и законных интересов оператора или третьих лиц либо для достижения общественно значимых целей при условии, что при этом не нарушаются права и свободы субъекта персональных данных.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">7.6.</span><span>Осуществляется обработка персональных данных, доступ неограниченного круга лиц к которым предоставлен субъектом персональных данных либо по его просьбе (далее — общедоступные персональные данные).</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">7.7.</span><span>Осуществляется обработка персональных данных, подлежащих опубликованию или обязательному раскрытию в соответствии с федеральным законом.</span></p>\r\n\r\n<h2 id=\"p8\">8. Порядок сбора, хранения, передачи и других видов обработки персональных данных</h2>\r\n<p>Безопасность персональных данных, которые обрабатываются Оператором, обеспечивается путем реализации правовых, организационных и технических мер, необходимых для выполнения в полном объеме требований действующего законодательства в области защиты персональных данных.</p>\r\n<p class=\"page-clause\"><span class=\"page-num\">8.1.</span><span>Оператор обеспечивает сохранность персональных данных и принимает все возможные меры, исключающие доступ к персональным данным неуполномоченных лиц.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">8.2.</span><span>Персональные данные Пользователя никогда, ни при каких условиях не будут переданы третьим лицам, за исключением случаев, связанных с исполнением действующего законодательства либо в случае, если субъектом персональных данных дано согласие Оператору на передачу данных третьему лицу для исполнения обязательств по гражданско-правовому договору.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">8.3.</span><span>В случае выявления неточностей в персональных данных Пользователь может актуализировать их самостоятельно, направив Оператору уведомление на адрес электронной почты <a href=\"mailto:info@homebread.ru\">info@homebread.ru</a> с пометкой «Актуализация персональных данных».</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">8.4.</span><span>Срок обработки персональных данных определяется достижением целей, для которых были собраны персональные данные, если иной срок не предусмотрен договором или действующим законодательством. Пользователь может в любой момент отозвать свое согласие на обработку персональных данных, направив Оператору уведомление посредством электронной почты на адрес <a href=\"mailto:info@homebread.ru\">info@homebread.ru</a> с пометкой «Отзыв согласия на обработку персональных данных».</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">8.5.</span><span>Вся информация, которая собирается сторонними сервисами, в том числе платежными системами, средствами связи и другими поставщиками услуг, хранится и обрабатывается указанными лицами (Операторами) в соответствии с их Пользовательским соглашением и Политикой конфиденциальности. Субъект персональных данных и/или с указанными документами. Оператор не несет ответственность за действия третьих лиц, в том числе указанных в настоящем пункте поставщиков услуг.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">8.6.</span><span>Установленные субъектом персональных данных запреты на передачу (кроме предоставления доступа), а также на обработку или условия обработки (кроме получения доступа) персональных данных, разрешенных для распространения, не действуют в случаях обработки персональных данных в государственных, общественных и иных публичных интересах, определенных законодательством РФ.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">8.7.</span><span>Оператор при обработке персональных данных обеспечивает конфиденциальность персональных данных.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">8.8.</span><span>Оператор осуществляет хранение персональных данных в форме, позволяющей определить субъекта персональных данных, не дольше, чем этого требуют цели обработки персональных данных, если срок хранения персональных данных не установлен федеральным законом, договором, стороной которого, выгодоприобретателем или поручителем по которому является субъект персональных данных.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">8.9.</span><span>Условием прекращения обработки персональных данных может являться достижение целей обработки персональных данных, истечение срока действия согласия субъекта персональных данных, отзыв согласия субъектом персональных данных или требование о прекращении обработки персональных данных, а также выявление неправомерной обработки персональных данных.</span></p>\r\n\r\n<h2 id=\"p9\">9. Перечень действий, производимых Оператором с полученными персональными данными</h2>\r\n<p class=\"page-clause\"><span class=\"page-num\">9.1.</span><span>Оператор осуществляет сбор, запись, систематизацию, накопление, хранение, уточнение (обновление, изменение), извлечение, использование, передачу (распространение, предоставление, доступ), обезличивание, блокирование, удаление и уничтожение персональных данных.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">9.2.</span><span>Оператор осуществляет автоматизированную обработку персональных данных с получением и/или передачей полученной информации по информационно-телекоммуникационным сетям или без таковой.</span></p>\r\n\r\n<h2 id=\"p10\">10. Трансграничная передача персональных данных</h2>\r\n<p class=\"page-clause\"><span class=\"page-num\">10.1.</span><span>Оператор до начала осуществления деятельности по трансграничной передаче персональных данных обязан уведомить уполномоченный орган по защите прав субъектов персональных данных о своем намерении осуществлять трансграничную передачу персональных данных (такое уведомление направляется отдельно от уведомления о намерении осуществлять обработку персональных данных).</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">10.2.</span><span>Оператор до подачи вышеуказанного уведомления обязан получить от органов власти иностранного государства, иностранных физических лиц, иностранных юридических лиц, которым планируется трансграничная передача персональных данных, соответствующие сведения.</span></p>\r\n\r\n<h2 id=\"p11\">11. Конфиденциальность персональных данных</h2>\r\n<p>Оператор и иные лица, получившие доступ к персональным данным, обязаны не раскрывать третьим лицам и не распространять персональные данные без согласия субъекта персональных данных, если иное не предусмотрено федеральным законом.</p>\r\n\r\n<h2 id=\"p12\">12. Заключительные положения</h2>\r\n<p class=\"page-clause\"><span class=\"page-num\">12.1.</span><span>Пользователь может получить любые разъяснения по интересующим вопросам, касающимся обработки его персональных данных, обратившись к Оператору с помощью электронной почты <a href=\"mailto:info@homebread.ru\">info@homebread.ru</a>.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">12.2.</span><span>В данном документе будут отражены любые изменения политики обработки персональных данных Оператором. Политика действует бессрочно до замены ее новой версией.</span></p>\r\n<p class=\"page-clause\"><span class=\"page-num\">12.3.</span><span>Актуальная версия Политики в свободном доступе расположена в сети Интернет по адресу <a href=\"https://homemadebread.ru/privacy\">https://homemadebread.ru/privacy</a>.</span></p>\r\n\r\n<div class=\"page-note\">\r\n    <h3>Как связаться по вопросам персональных данных</h3>\r\n    <p>Напишите на <a href=\"mailto:info@homebread.ru\">info@homebread.ru</a>: для уточнения данных — с пометкой «Актуализация персональных данных», для отзыва согласия — с пометкой «Отзыв согласия на обработку персональных данных».</p>\r\n</div>', 1, 0);

CREATE TABLE `portfolio` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `slug` varchar(200) NOT NULL,
  `description` text DEFAULT NULL,
  `product_id` int(11) DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `gallery` longtext DEFAULT NULL,
  `price_approx` decimal(10,2) DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `sort_order` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `product_id` (`product_id`),
  CONSTRAINT `portfolio_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `promotions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `slug` varchar(200) NOT NULL,
  `description` text DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `discount` varchar(50) DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `sort_order` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `reviews` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_name` varchar(100) NOT NULL,
  `customer_phone` varchar(20) DEFAULT NULL,
  `customer_email` varchar(100) DEFAULT NULL,
  `rating` tinyint(4) DEFAULT 5,
  `text` text NOT NULL,
  `image` varchar(255) DEFAULT NULL,
  `is_approved` tinyint(1) DEFAULT 0,
  `is_visible` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `approved_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `articles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `slug` varchar(200) NOT NULL,
  `excerpt` text DEFAULT NULL,
  `content` longtext DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `meta_title` varchar(200) DEFAULT NULL,
  `meta_description` varchar(300) DEFAULT NULL,
  `views` int(11) DEFAULT 0,
  `is_published` tinyint(1) DEFAULT 1,
  `published_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `setting_key` varchar(100) NOT NULL,
  `setting_value` text DEFAULT NULL,
  `setting_group` varchar(50) DEFAULT 'general',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `setting_key` (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

